import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { LOCALE_STORAGE_KEY, getLocaleConfig, type AppLocale } from '@/locales'

/**
 * 统一语言切换入口：同时驱动 vue-i18n locale、Element Plus locale 与
 * localStorage 持久化，避免各处各自为政导致不同步。
 *
 * 语言配置集中在 @/locales 的 SUPPORTED_LOCALES，加语言无需改动本文件。
 */
export function useLocale() {
  const { locale } = useI18n()

  const current = computed<AppLocale>(() => locale.value)

  // 当前语言的配置（Element Plus 内置文案、日期格式）从配置表查，无效 code 回退默认
  const config = computed(() => getLocaleConfig(current.value))

  // Element Plus 内置文案（分页、日期、弹窗确认/取消等）随当前语言切换
  const elLocale = computed(() => config.value.elLocale)

  // 日期格式化的 BCP47 tag，供 toLocaleString 使用
  const dateLocale = computed(() => config.value.dateLocale)

  function setLocale(l: AppLocale) {
    locale.value = l
    localStorage.setItem(LOCALE_STORAGE_KEY, l)
  }

  return { locale: current, elLocale, dateLocale, setLocale }
}
