import { defineStore } from 'pinia'
import { computed, ref } from 'vue'
import apiClient from '@/api/client'

export type UserRole = 'admin' | 'viewer'

export interface User {
  id: number
  username: string
  is_active: boolean
  created_at: string
  role: UserRole
}

export const useAuthStore = defineStore('auth', () => {
  const user = ref<User | null>(null)
  const initialized = ref(false)

  const isLoggedIn = computed(() => !!user.value)
  const isAdmin = computed(() => user.value?.role === 'admin')
  const isViewer = computed(() => user.value?.role === 'viewer')

  function setUser(value: User | null) {
    user.value = value
    if (value) {
      localStorage.setItem('chaosops-user', JSON.stringify(value))
    } else {
      localStorage.removeItem('chaosops-user')
    }
  }

  function loadFromStorage() {
    const storedUser = localStorage.getItem('chaosops-user')
    if (storedUser) {
      try {
        user.value = JSON.parse(storedUser)
      } catch {
        user.value = null
      }
    }
  }

  /**
   * 应用启动时调用：通过 httpOnly cookie 向后端确认登录状态。
   * 成功后恢复用户信息；失败则清空状态。
   */
  async function initialize() {
    try {
      const { data } = await apiClient.get<User>('/v1/auth/me')
      setUser(data)
    } catch {
      setUser(null)
    } finally {
      initialized.value = true
    }
  }

  /**
   * 登出：调用后端清除 cookie，并清空前端用户状态。
   * @param callBackend 是否调用后端 logout；响应拦截器触发时传 false 避免循环。
   */
  async function logout(callBackend = true) {
    if (callBackend) {
      try {
        await apiClient.post('/v1/auth/logout')
      } catch {
        // 即使后端失败也清空前端状态
      }
    }
    setUser(null)
  }

  return {
    user,
    initialized,
    isLoggedIn,
    isAdmin,
    isViewer,
    setUser,
    loadFromStorage,
    initialize,
    logout,
  }
})
