import axios, { AxiosError } from 'axios'

import { LOCALE_STORAGE_KEY } from '@/locales'

const apiClient = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL || '/api',
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
  // 后端通过 httpOnly cookie 鉴权，必须携带凭证
  withCredentials: true,
})

// 统一注入 Accept-Language：后端 AI prompt 按此选择输出语言（默认 zh）。
// 每次请求时读 localStorage，保证切换语言后立刻生效。
apiClient.interceptors.request.use((config) => {
  const locale = localStorage.getItem(LOCALE_STORAGE_KEY) === 'en' ? 'en' : 'zh'
  config.headers['Accept-Language'] = locale
  return config
})

apiClient.interceptors.response.use(
  (response) => response,
  async (error: AxiosError) => {
    if (error.response?.status === 401) {
      // 动态导入避免与 auth store / router 形成循环依赖
      const [{ useAuthStore }, router] = await Promise.all([
        import('@/stores/auth'),
        import('@/router'),
      ])
      const authStore = useAuthStore()
      authStore.logout(false)
      router.default.push('/login')
    }
    return Promise.reject(error)
  }
)

export function getApiBaseUrl(): string {
  return import.meta.env.VITE_API_BASE_URL || ''
}

export function getWsBaseUrl(): string {
  const apiBase = getApiBaseUrl()
  if (apiBase) {
    return apiBase.replace(/^http/, 'ws')
  }
  // 默认使用当前页面 host，避免生成 ws/ws/v1/dashboard 这类无效 URL
  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
  return `${protocol}//${window.location.host}`
}

export default apiClient
