import { createI18n } from 'vue-i18n'
import zhCn from 'element-plus/es/locale/lang/zh-cn'
import enLocale from 'element-plus/es/locale/lang/en'
import zh from './zh'
import en from './en'

// 语言持久化 key，全站统一。
export const LOCALE_STORAGE_KEY = 'chaosops-locale'

/**
 * 语言配置表——本应用支持的全部语言在这里集中登记。
 *
 * 加一种新语言只需两步，无需改动切换器/useLocale/i18n 任何代码：
 *   1. 在本表加一项（import 对应 Element Plus locale 与翻译文件）
 *   2. 新建一个 <code>.ts 翻译文件（key 与 zh/en 对齐，i18n.spec.ts 机器校验）
 */
export interface LocaleConfig {
  code: string // 语言代码（localStorage 存储值 / Accept-Language 用）
  label: string // 切换器下拉显示名
  shortLabel: string // 顶栏按钮短标签
  elLocale: typeof zhCn // Element Plus 内置文案（分页/日期/弹窗按钮等）
  dateLocale: string // 日期格式化 BCP47 tag
  messages: typeof zh // 该语言翻译包
}

export const SUPPORTED_LOCALES: LocaleConfig[] = [
  { code: 'zh', label: '中文', shortLabel: '中', elLocale: zhCn, dateLocale: 'zh-CN', messages: zh },
  { code: 'en', label: 'English', shortLabel: 'EN', elLocale: enLocale, dateLocale: 'en-US', messages: en },
]

// 默认语言必须是中文（E2E 依赖中文选择器）。
export const DEFAULT_LOCALE = 'zh'

export type AppLocale = string

const defaultConfig = SUPPORTED_LOCALES.find((l) => l.code === DEFAULT_LOCALE) ?? SUPPORTED_LOCALES[0]

/** 按 code 取语言配置，无效 code 回退默认语言（兜底不崩）。 */
export function getLocaleConfig(code: string): LocaleConfig {
  return SUPPORTED_LOCALES.find((l) => l.code === code) ?? defaultConfig
}

function isSupported(code: string | null): boolean {
  return !!code && SUPPORTED_LOCALES.some((l) => l.code === code)
}

// 默认语言必须是中文（E2E 依赖中文选择器），且不能跟随浏览器语言
// （Playwright 默认 en-US，跟随浏览器会导致 E2E 全挂）。
// 仅当 localStorage 中显式存了受支持的语言时才切换。
function getInitialLocale(): AppLocale {
  const saved = localStorage.getItem(LOCALE_STORAGE_KEY)
  return isSupported(saved) ? (saved as string) : DEFAULT_LOCALE
}

const messages = Object.fromEntries(
  SUPPORTED_LOCALES.map((l) => [l.code, l.messages]),
) as Record<string, typeof zh>

const i18n = createI18n({
  legacy: false,
  locale: getInitialLocale(),
  fallbackLocale: DEFAULT_LOCALE,
  messages,
})

export default i18n
